const DQ = /@dqventures\.com$/i;
const stripHtml = (html) => String(html || '')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(p|div|li|ul|ol|h[1-6])>/gi, '\n')
  .replace(/<[^>]*>/g, '')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>');

const out = [];
for (const item of $input.all()) {
  const ev = item.json || {};
  const summary = String(ev.summary || '');
  if (!/interview/i.test(summary)) continue;
  if (ev.status === 'cancelled') continue;

  const lines = stripHtml(ev.description).split('\n').map(s => s.trim()).filter(Boolean);
  let name = '';
  let email = '';
  const idx = lines.findIndex(l => /^booked by\b/i.test(l));
  if (idx >= 0) {
    for (let i = idx + 1; i < Math.min(lines.length, idx + 6); i++) {
      const line = lines[i];
      const m = line.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);
      if (m) {
        if (!email) email = m[0];
        if (name) break;
        continue;
      }
      if (!name && line.length <= 80) name = line;
      if (name && email) break;
    }
  }
  if (!name) {
    const m = summary.match(/\(([^()]+)\)\s*$/);
    if (m) name = m[1];
  }
  name = String(name).replace(/\s+/g, ' ').trim();
  email = String(email).trim().toLowerCase();

  if (!email) {
    const guests = (ev.attendees || []).filter(a => a && a.email && !DQ.test(a.email) && a.resource !== true);
    if (guests.length === 1) email = String(guests[0].email).trim().toLowerCase();
  }

  if (!email && !name) continue;

  const start = ev.start || {};
  const rawStart = start.dateTime || start.date || '';
  const interviewDate = String(rawStart).slice(0, 10);
  const gp = (ev.organizer && ev.organizer.email) || (ev.creator && ev.creator.email) || '';

  out.push({
    json: {
      eventId: ev.id || '',
      eventTitle: summary,
      eventLink: ev.htmlLink || '',
      eventStart: rawStart,
      interviewDate,
      gpEmail: gp,
      name,
      email,
      folkEmailUrl: 'https://api.folk.app/v1/people?limit=50&filter[emails][eq]=' + encodeURIComponent(email || 'no-email-on-invite@example.invalid'),
      folkNameUrl: 'https://api.folk.app/v1/people?limit=50&filter[fullName][like]=' + encodeURIComponent(name || '__no_name_on_invite__'),
    },
  });
}
return out;

const GROUP = 'grp_411ea0ed-822d-4de9-80de-1a0512da709e';
const ADVANCE_FROM = ['', 'lead', 'applied', 'qualified', 'invited to interview', 'interview booked'];

const booking = $('Extract Booking').item.json;
const emailRes = $('Find Lead By Email').item.json || {};
const nameRes = $input.item.json || {};

const emailItems = ((emailRes.data || {}).items) || [];
const nameItems = ((nameRes.data || {}).items) || [];
const inGroup = (p) => (p.groups || []).some(g => g.id === GROUP);
const statusOf = (p) => String((((p.customFieldValues || {})[GROUP]) || {}).Status || '').trim();

let person = null;
let route = '';
let reason = '';

const emailMatches = booking.email ? emailItems.filter(inGroup) : [];

if (emailMatches.length === 1) {
  person = emailMatches[0];
  route = 'email';
} else if (emailMatches.length > 1) {
  reason = emailMatches.length + ' people in Leads & Applications share the email ' + booking.email + ', so the match is ambiguous.';
} else {
  const nameMatches = booking.name
    ? nameItems.filter(p => inGroup(p) && statusOf(p).toLowerCase() === 'invited to interview')
    : [];
  if (nameMatches.length === 1) {
    person = nameMatches[0];
    route = 'name';
  } else if (nameMatches.length > 1) {
    reason = 'No Leads & Applications record has the email ' + (booking.email || 'none on the invite') + ', and the name "' + booking.name + '" matches ' + nameMatches.length + ' people sitting at "Invited to interview", so the match is ambiguous.';
  } else if (emailItems.length > 0) {
    reason = 'The email ' + booking.email + ' exists in Folk but not in the Leads & Applications group, and nobody named "' + booking.name + '" is sitting at "Invited to interview".';
  } else {
    reason = 'Nobody in Leads & Applications has the email ' + (booking.email || 'none on the invite') + ', and nobody named "' + booking.name + '" is sitting at "Invited to interview".';
  }
}

const head = ':calendar: *Interview booked, but Folk was not updated*';
const context = [
  '*Applicant:* ' + (booking.name || 'no name on the invite') + ' <' + (booking.email || 'no email on the invite') + '>',
  '*Interviewer:* ' + (booking.gpEmail || 'unknown'),
  '*Interview date:* ' + (booking.interviewDate || 'unknown'),
  '*Event:* ' + booking.eventTitle + (booking.eventLink ? ' - ' + booking.eventLink : ''),
];

if (!person) {
  return {
    json: {
      update: false,
      reason,
      alertText: [head].concat(context, ['*Why:* ' + reason, 'Nothing was written. Match the person by hand in Folk and set the status yourself.']).join('\n'),
    },
  };
}

const currentStatus = statusOf(person);
if (ADVANCE_FROM.indexOf(currentStatus.toLowerCase()) === -1) {
  const why = (person.fullName || booking.name) + ' is already at "' + currentStatus + '", which is past Interview Booked, so nothing was changed.';
  return {
    json: {
      update: false,
      reason: why,
      alertText: [head].concat(context, ['*Why:* ' + why, 'Update the record by hand if this booking should move them.']).join('\n'),
    },
  };
}

const fields = { Status: 'Interview Booked' };
if (booking.interviewDate) fields['Interview Date'] = booking.interviewDate;

const updateBody = { customFieldValues: {} };
updateBody.customFieldValues[GROUP] = fields;

let emailAdded = false;
if (route === 'name' && booking.email) {
  const existing = (person.emails || []).map(e => String(e).trim()).filter(Boolean);
  if (!existing.some(e => e.toLowerCase() === booking.email)) {
    updateBody.emails = existing.concat([booking.email]).slice(0, 20);
    emailAdded = true;
  }
}

return {
  json: {
    update: true,
    route,
    emailAdded,
    personId: person.id,
    personName: person.fullName || booking.name,
    previousStatus: currentStatus || '(blank)',
    interviewDate: booking.interviewDate || '',
    applicantEmail: booking.email,
    eventTitle: booking.eventTitle,
    updateBody,
  },
};
